(function(){function initPortfolio(wrapper){if(!wrapper){return}
if(typeof wrapper._dancepadPortfolioCleanup==="function"){wrapper._dancepadPortfolioCleanup()}
var bgImage=wrapper.querySelector(".dan-portfolio__bg-image");var projectsContainer=wrapper.querySelector(".dan-portfolio__projects");var items=Array.prototype.slice.call(wrapper.querySelectorAll(".dan-portfolio__item"));if(!bgImage||!projectsContainer||!items.length){return}
var bgOpacity=parseFloat(wrapper.getAttribute("data-bg-opacity"));var bgScale=parseFloat(wrapper.getAttribute("data-bg-scale"));var bgScaleEnd=parseFloat(wrapper.getAttribute("data-bg-scale-end"));bgOpacity=Number.isFinite(bgOpacity)?bgOpacity:1;bgScale=Number.isFinite(bgScale)?bgScale:1.2;bgScaleEnd=Number.isFinite(bgScaleEnd)?bgScaleEnd:1;function showImage(imageUrl){if(!imageUrl){return}
bgImage.style.transition="none";bgImage.style.transform="scale("+bgScale+")";bgImage.src=imageUrl;bgImage.style.opacity=String(bgOpacity);requestAnimationFrame(function(){requestAnimationFrame(function(){var duration=getComputedStyle(wrapper).getPropertyValue("--dan-portfolio-zoom-duration").trim()||"0.8s";bgImage.style.transition="transform "+duration+" cubic-bezier(0.25, 0.46, 0.45, 0.94)";bgImage.style.transform="scale("+bgScaleEnd+")"})})}
var itemListeners=[];items.forEach(function(item){var imageUrl=item.getAttribute("data-image");if(!imageUrl){return}
var preloadImage=new Image();preloadImage.crossOrigin="anonymous";preloadImage.src=imageUrl;var enterHandler=function(){showImage(imageUrl)};item.addEventListener("mouseenter",enterHandler);item.addEventListener("focusin",enterHandler);itemListeners.push({item:item,handler:enterHandler})});var leaveHandler=function(){bgImage.style.opacity="0"};var focusOutHandler=function(event){if(!projectsContainer.contains(event.relatedTarget)){leaveHandler()}};projectsContainer.addEventListener("mouseleave",leaveHandler);projectsContainer.addEventListener("focusout",focusOutHandler);wrapper._dancepadPortfolioCleanup=function(){itemListeners.forEach(function(listener){listener.item.removeEventListener("mouseenter",listener.handler);listener.item.removeEventListener("focusin",listener.handler)});projectsContainer.removeEventListener("mouseleave",leaveHandler);projectsContainer.removeEventListener("focusout",focusOutHandler)}}
function initAll(){document.querySelectorAll(".dan-portfolio").forEach(initPortfolio)}
window.dancepad_portfolio=initAll;if(document.readyState==="loading"){document.addEventListener("DOMContentLoaded",initAll)}else{initAll()}})()